import { test, expect } from '@playwright/test';

test.describe('Payment Card Declined Error States', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/checkout');
    await page.waitForLoadState('networkidle');
  });

  test('should display clear error message when card is declined', async ({ page }) => {
    // Fill in payment form with declined card number
    await page.getByLabel('Card Number').fill('4000000000000002');
    await page.getByLabel('Expiry Date').fill('12/25');
    await page.getByLabel('CVV').fill('123');
    await page.getByLabel('Cardholder Name').fill('John Doe');

    // Submit payment
    await page.getByRole('button', { name: /pay|submit|complete payment/i }).click();

    // Verify error message is displayed
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText(/card.*declined|payment.*failed|declined/i);
  });

  test('should show error with specific decline reason', async ({ page }) => {
    // Fill in payment form
    await page.getByLabel('Card Number').fill('4000000000000002');
    await page.getByLabel('Expiry Date').fill('12/25');
    await page.getByLabel('CVV').fill('123');
    await page.getByLabel('Cardholder Name').fill('Jane Smith');

    // Submit payment
    await page.getByRole('button', { name: /pay|submit|complete payment/i }).click();

    // Verify error message contains helpful information
    const errorAlert = page.getByRole('alert');
    await expect(errorAlert).toBeVisible();

    // Check for specific error details
    const errorText = await errorAlert.textContent();
    expect(errorText).toBeTruthy();
    expect(errorText?.toLowerCase()).toMatch(/declined|insufficient|lost|stolen|expired|invalid/i);
  });

  test('should allow retry after card decline error', async ({ page }) => {
    // First attempt with declined card
    await page.getByLabel('Card Number').fill('4000000000000002');
    await page.getByLabel('Expiry Date').fill('12/25');
    await page.getByLabel('CVV').fill('123');
    await page.getByLabel('Cardholder Name').fill('John Doe');

    await page.getByRole('button', { name: /pay|submit|complete payment/i }).click();

    // Verify error is shown
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();

    // Clear the form and retry with valid card
    await page.getByLabel('Card Number').clear();
    await page.getByLabel('Card Number').fill('4242424242424242');
    await page.getByLabel('Expiry Date').clear();
    await page.getByLabel('Expiry Date').fill('12/25');
    await page.getByLabel('CVV').clear();
    await page.getByLabel('CVV').fill('123');

    // Submit again
    await page.getByRole('button', { name: /pay|submit|complete payment/i }).click();

    // Verify success or that error is cleared
    await expect(errorMessage).not.toBeVisible();
  });

  test('should display error message in accessible format', async ({ page }) => {
    // Fill in payment form with declined card
    await page.getByLabel('Card Number').fill('4000000000000002');
    await page.getByLabel('Expiry Date').fill('12/25');
    await page.getByLabel('CVV').fill('123');
    await page.getByLabel('Cardholder Name').fill('John Doe');

    // Submit payment
    await page.getByRole('button', { name: /pay|submit|complete payment/i }).click();

    // Verify error is in an alert role for accessibility
    const errorAlert = page.getByRole('alert');
    await expect(errorAlert).toBeVisible();

    // Verify the error message is readable
    const errorText = await errorAlert.textContent();
    expect(errorText?.length).toBeGreaterThan(10);
    expect(errorText).not.toContain('Error code:');
  });

  test('should persist error message until user takes action', async ({ page }) => {
    // Fill in payment form with declined card
    await page.getByLabel('Card Number').fill('4000000000000002');
    await page.getByLabel('Expiry Date').fill('12/25');
    await page.getByLabel('CVV').fill('123');
    await page.getByLabel('Cardholder Name').fill('John Doe');

    // Submit payment
    await page.getByRole('button', { name: /pay|submit|complete payment/i }).click();

    // Verify error is shown
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();

    // Wait a moment and verify error is still visible
    await page.waitForTimeout(2000);
    await expect(errorMessage).toBeVisible();

    // Error should only disappear when user modifies the form
    await page.getByLabel('Card Number').clear();
    await page.getByLabel('Card Number').fill('4242424242424242');

    // Error should be cleared or hidden after user action
    await expect(errorMessage).not.toBeVisible();
  });
});
